```js
(async () => {
  const BATCH_SIZE = 12;
  const DELAY_MS = 500;
  let allPosts = [];
  let offset = 0;
  let hasMore = true;

  console.log("Starting SemiAnalysis article fetch...");

  while (hasMore) {
    try {
      const res = await fetch(
        `/api/v1/posts?offset=${offset}&limit=${BATCH_SIZE}`,
        { credentials: "include" }
      );
      if (!res.ok) {
        console.error(`Failed at offset ${offset}: ${res.status}`);
        break;
      }
      const posts = await res.json();
      if (posts.length === 0) {
        hasMore = false;
      } else {
        allPosts = allPosts.concat(posts);
        offset += posts.length;
        console.log(`Fetched ${allPosts.length} post metadata entries...`);
        await new Promise((r) => setTimeout(r, DELAY_MS));
      }
    } catch (err) {
      console.error(`Error at offset ${offset}:`, err);
      break;
    }
  }

  console.log(`Total posts found: ${allPosts.length}`);
  console.log("Now fetching full article content for each post...");

  const fullPosts = [];
  for (let i = 0; i < allPosts.length; i++) {
    const post = allPosts[i];
    const slug = post.slug;
    try {
      const res = await fetch(`/api/v1/posts/${slug}`, {
        credentials: "include",
      });
      if (!res.ok) {
        console.warn(`Failed to fetch post "${slug}": ${res.status}`);
        fullPosts.push({
          slug: slug,
          title: post.title,
          subtitle: post.subtitle,
          date: post.post_date,
          audience: post.audience,
          canonical_url: post.canonical_url,
          body_html: post.body_html || null,
          error: `HTTP ${res.status}`,
        });
      } else {
        const full = await res.json();
        fullPosts.push({
          slug: full.slug,
          title: full.title,
          subtitle: full.subtitle,
          date: full.post_date,
          audience: full.audience,
          canonical_url: full.canonical_url,
          body_html: full.body_html,
          authors: (full.publishedBylines || []).map((b) => b.name),
          word_count: full.word_count,
          description: full.description,
        });
      }
      console.log(
        `[${i + 1}/${allPosts.length}] Fetched: ${post.title}`
      );
      await new Promise((r) => setTimeout(r, DELAY_MS));
    } catch (err) {
      console.error(`Error fetching "${slug}":`, err);
      fullPosts.push({
        slug: slug,
        title: post.title,
        date: post.post_date,
        canonical_url: post.canonical_url,
        body_html: null,
        error: err.message,
      });
    }
  }

  const blob = new Blob([JSON.stringify(fullPosts, null, 2)], {
    type: "application/json",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "semianalysis_articles.json";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  console.log(
    `Done! Downloaded ${fullPosts.length} articles as semianalysis_articles.json`
  );
})();
```

Once the JSON downloads, come back here and run:

```bash
pip install markdownify
python semianalysis-scraper/convert_to_markdown.py ~/Downloads/semianalysis_articles.json articles/
```
